"use client"

import * as React from "react"
import { NumberField as NumberFieldPrimitive } from "@base-ui/react/number-field"
import { cn } from "cn"
import { MinusIcon, PlusIcon } from "lucide-react"

import { InputGroupAddon, InputGroupButton } from "@/components/ui/input-group"

function NumberField({
  className,
  disabled,
  ...props
}: Omit<NumberFieldPrimitive.Root.Props, "className"> & {
  className?: string
}) {
  return (
    <NumberFieldPrimitive.Root
      data-slot="number-field"
      data-disabled={disabled ? "true" : undefined}
      role="group"
      disabled={disabled}
      className={cn(
        "border-transparent border-b-input bg-transparent has-[[data-slot=input-group-control]:focus-visible]:border-b-ring has-[[data-slot][aria-invalid=true]]:border-b-destructive dark:has-[[data-slot][aria-invalid=true]]:border-b-destructive/50 h-10 rounded-none border transition-[color,border-color] in-data-[slot=combobox-content]:focus-within:border-inherit in-data-[slot=combobox-content]:focus-within:ring-0 has-data-[align=block-end]:rounded-none has-data-[align=block-start]:rounded-none has-[textarea]:rounded-none has-[>[data-align=block-end]]:h-auto has-[>[data-align=block-end]]:flex-col has-[>[data-align=block-start]]:h-auto has-[>[data-align=block-start]]:flex-col has-[>[data-align=block-end]]:[&>input]:pt-3 has-[>[data-align=block-start]]:[&>input]:pb-3 group/input-group relative flex w-32 min-w-0 items-center outline-none",
        className
      )}
      {...props}
    />
  )
}

function NumberFieldInput({
  className,
  ...props
}: Omit<NumberFieldPrimitive.Input.Props, "className"> & {
  className?: string
}) {
  return (
    <NumberFieldPrimitive.Input
      data-slot="input-group-control"
      className={cn(
        "border-transparent border-b-input focus-visible:border-b-ring aria-invalid:border-b-destructive dark:aria-invalid:border-b-destructive/50 h-10 px-0 py-1 text-base transition-[color,border-color] file:h-7 file:text-sm file:font-medium md:text-sm border-0 bg-transparent ring-0 focus-visible:ring-0 aria-invalid:ring-0 dark:bg-transparent group-has-[>[data-align=inline-start]]/input-group:pl-2 group-has-[>[data-align=inline-end]]/input-group:pr-2 w-full min-w-0 flex-1 text-center tabular-nums outline-none placeholder:text-muted-foreground disabled:pointer-events-none disabled:cursor-not-allowed disabled:opacity-50",
        className
      )}
      {...props}
    />
  )
}

function NumberFieldDecrement({
  children,
  "aria-label": ariaLabel = "Decrease",
  ...props
}: NumberFieldPrimitive.Decrement.Props) {
  return (
    <InputGroupAddon align="inline-start">
      <NumberFieldPrimitive.Decrement
        data-slot="number-field-decrement"
        aria-label={ariaLabel}
        render={<InputGroupButton size="icon-xs" />}
        {...props}
      >
        {children ?? <MinusIcon aria-hidden="true" />}
      </NumberFieldPrimitive.Decrement>
    </InputGroupAddon>
  )
}

function NumberFieldIncrement({
  children,
  "aria-label": ariaLabel = "Increase",
  ...props
}: NumberFieldPrimitive.Increment.Props) {
  return (
    <InputGroupAddon align="inline-end">
      <NumberFieldPrimitive.Increment
        data-slot="number-field-increment"
        aria-label={ariaLabel}
        render={<InputGroupButton size="icon-xs" />}
        {...props}
      >
        {children ?? <PlusIcon aria-hidden="true" />}
      </NumberFieldPrimitive.Increment>
    </InputGroupAddon>
  )
}

export {
  NumberField,
  NumberFieldDecrement,
  NumberFieldIncrement,
  NumberFieldInput,
}
